from typing import List

def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse left to right for even rows
            for j in range(0, len(grid[i]), 2):
                result.append(grid[i][j])
        else:
            # Traverse right to left for odd rows
            for j in range(1, len(grid[i]), 2):
                result.append(grid[i][len(grid[i]) - j])
    return result

def findValidPair(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            first_digit = int(s[i])
            second_digit = int(s[i + 1])
            if counts[s[i]] == first_digit and counts[s[i + 1]] == second_digit:
                return s[i] + s[i + 1]
    return ""

