from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0] if coins[0][0] >= 0 else 0
    dp[0][0][1] = 0 if coins[0][0] < 0 else coins[0][0]

    for i in range(m):
        for j in range(n):
            for k in range(3):
                if i == 0 and j == 0:
                    continue
                current_coins = coins[i][j]
                if current_coins < 0:
                    if k > 0:
                        # If we neutralize this robber
                        dp[i][j][k] = max(dp[i][j][k], (dp[i - 1][j][k - 1] if i > 0 else -float('inf')) + 0)
                        dp[i][j][k] = max(dp[i][j][k], (dp[i][j - 1][k - 1] if j > 0 else -float('inf')) + 0)
                else:
                    # Normal coins
                    if i > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k] + current_coins)
                    if j > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k] + current_coins)

    result = max(dp[m - 1][n - 1])
    return result if result > 0 else 0

from typing import List
from collections import defaultdict, deque


def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    # Create a reversed graph as an adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[v].append((u, w))  # reverse the direction to focus on reachability to node 0

    # Define a binary search over the possible maximum weights
    left, right = 1, 10**6
    result = -1

    while left <= right:
        mid = (left + right) // 2

        # Check if we can satisfy the conditions with max weight `mid`
        if canReachWithMaxWeight(graph, n, threshold, mid):
            result = mid  # we can satisfy the conditions, try for a smaller max weight
            right = mid - 1
        else:
            left = mid + 1

    return result


def canReachWithMaxWeight(graph: List[List[tuple]], n: int, threshold: int, maxWeight: int) -> bool:
    out_edges_count = [0] * n
    queue = deque([0])  # Start BFS from node 0
    reachable = [False] * n
    reachable[0] = True

    while queue:
        node = queue.popleft()
        for neighbor, weight in graph[node]:
            if weight <= maxWeight and out_edges_count[node] < threshold:
                if not reachable[neighbor]:
                    reachable[neighbor] = True
                    queue.append(neighbor)
                out_edges_count[node] += 1

    # Ensure all nodes except 0 can reach node 0
    return all(reachable[i] for i in range(1, n))

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in events:
        event_type, timestamp, *data = event
        timestamp = int(timestamp)

        # Update online status based on OFFLINE events
        if event_type == "OFFLINE":
            user_id = int(data[0])  # extract id number from plain "<number>"
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60

        # Handle MESSAGE events
        elif event_type == "MESSAGE":
            # Process any users going back online at this timestamp
            for i in range(numberOfUsers):
                if not online_status[i] and timestamp >= offline_until[i]:
                    online_status[i] = True

            mentions_string = data[0]
            if mentions_string == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == "HERE":
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                ids = mentions_string.split()
                for uid in ids:
                    if uid == "ALL":
                        for i in range(numberOfUsers):
                            mentions[i] += 1
                    elif uid == "HERE":
                        for i in range(numberOfUsers):
                            if online_status[i]:
                                mentions[i] += 1
                    else:
                        user_id = int(uid[2:])  # extract id number from "id<number>"
                        mentions[user_id] += 1

    return mentions
